"""Recorded real-robot control driver. Uses only rcb_client observations/specification.
Each command is saved before execution; --replay executes the recorded targets.
"""
import json, pathlib, argparse
import numpy as np
from rcb_client import Robot
OUT=pathlib.Path('/app/output')
class Controller:
 def __init__(self):
  self.r=Robot(); self.spec=self.r.spec(); self.layout=self.spec['action_types']['joint_position']['layout']; self.ranges=np.array(self.spec['action_types']['joint_position']['range_rad']); self.obs=self.r.get_obs(video='none'); self.q=self.current_targets()
 def current_targets(self):
  p=dict(zip(self.spec['proprio_layout'],self.obs.meta['proprio']['now'])); q=[]
  for a in self.layout:
   j=a.replace('_A_','_')
   q.append(p[j+'_pos'] if not j.endswith('J0') else p[j[:-1]+'1_pos']+p[j[:-1]+'2_pos'])
  return np.array(q)
 def move(self,q,steps=10,note=''):
  q=np.array(q); start=self.q.copy(); A=np.array([start+(q-start)*(i+1)/steps for i in range(steps)]); A=np.clip(2*(A-self.ranges[:,0])/(self.ranges[:,1]-self.ranges[:,0])-1,-1,1)
  rec={'actions':A.tolist(),'note':note}
  with open(OUT/'commands.jsonl','a') as f:f.write(json.dumps(rec)+'\n')
  res=self.r.submit('joint_position',A,cameras=['room_camera','left_eye_camera','right_eye_camera'],video='frames',note=note)
  self.obs=res; self.q=q; step=res.meta['control_steps']; res.save(OUT/f'step{step:04d}'); np.save(OUT/'target.npy',q); print('STEP',step,'done',res.done,'reason',res.meta.get('reason')); p=np.array(res.meta['proprio']['now']); print('body',np.round(p[:16],3),np.round(p[40:45],3),'imu',np.round(p[-6:],3)); return res
if __name__=='__main__':
 p=argparse.ArgumentParser(); p.add_argument('--replay',action='store_true'); args=p.parse_args()
 if args.replay:
  r=Robot()
  for line in open(OUT/'commands.jsonl'):
   c=json.loads(line); res=r.submit('joint_position',c['actions'],cameras=['room_camera'],video='none',note=c['note'])
   if res.done:break
  print(r.status())
 else: print(Robot().status())
PY
