import json,numpy as np
from scipy.spatial.transform import Rotation
S=json.load(open('/app/output/spec.json')); J=S['proprio']; L=S['links']; names=J['joints']; axes=np.array(J['axis']); points=np.array(J['position_m']); parents=L['parent']; links=L['names']; masses=np.array(L['mass_kg']); coms=np.array(L['com_m'])
# Every non-root link is joint child, in exactly the same order as joint specification.
def fk(q):
 T=[np.eye(4)]
 for i in range(69):
  R=Rotation.from_rotvec(axes[i]/np.linalg.norm(axes[i])*q[i]).as_matrix(); X=np.eye(4); X[:3,:3]=R; X[:3,3]=points[i]-R@points[i]; T.append(T[links.index(parents[i+1])]@X)
 return np.array(T)
def point(T,link,p):return T[links.index(link),:3,:3]@np.array(p)+T[links.index(link),:3,3]
def qfull(a):
 q=np.zeros(69)
 for name,val in zip(S['action_types']['joint_position']['layout'],a):
  name=name.replace('_A_','_')
  if name.endswith('J0'):
   q[names.index(name[:-1]+'1')]=val/2;q[names.index(name[:-1]+'2')]=val/2
  else:q[names.index(name)]=val
 return q
def body(a,pitch=0):
 T=fk(qfull(a)); R=Rotation.from_euler('y',pitch).as_matrix(); foot=point(T,'left_ankle_link',[.039,.203,-1.065]); base=np.array([.039,.203,0])-R@foot
 com=sum(m*(R@point(T,l,c)+base) for m,l,c in zip(masses,links,coms))/sum(masses)
 hands=[R@point(T,h,[.46,y,.087])+base for h,y in [('lh_palm',.214),('rh_palm',-.214)]]
 return base,com,np.array(hands)
