from gen import *
from kin import body
from scipy.optimize import brentq

def balance_pitch(q):
 def fun(p):
  a=q.copy();a[4]=a[9]=-p-a[2]-a[3];return body(a,p)[1][0]-.085
 p=brentq(fun,-.6,1.7);a=q.copy();a[4]=a[9]=-p-a[2]-a[3];return a,p

def plan(dest,steps):
 c=Controller(); start=c.current_targets(); rows=[]
 for i in range(1,steps+1):
  t=i/steps;t=t*t*(3-2*t);q,p=balance_pitch(start+(dest-start)*t);rows.append(np.r_[q,p])
 np.save(OUT/'trajectory.npy',rows);(OUT/'cursor').write_text('0')

def run(n):
 c=Controller(); rows=np.load(OUT/'trajectory.npy');cursor=int((OUT/'cursor').read_text());c.q=np.load(OUT/'target.npy')
 for i in range(cursor,min(cursor+n,len(rows))):
  q=rows[i,:61].copy();pd=rows[i,61];obs=np.array(c.obs.meta['proprio']['now']);pitch=np.arctan2(obs[-3],-obs[-1]);gyro=obs[-5]
  # ankle feedback stabilizes body pitch while tracking the balanced hinge.
  corr=np.clip(.75*(pitch-pd)+.16*gyro,-.3,.3);q[4]+=corr;q[9]+=corr
  roll=np.arctan2(obs[-2],-obs[-1]);q[1]+=.3*roll-.08*obs[-6];q[6]+=.3*roll-.08*obs[-6]
  res=c.move(q,1,f'trajectory {i+1}, pitch desired {pd:.4f}, observed {pitch:.4f}')
  (OUT/'cursor').write_text(str(i+1))
  if res.done:break
if __name__=='__main__':
 import sys
 if sys.argv[1]=='plan':plan(np.load(sys.argv[2]),int(sys.argv[3]))
 else:run(int(sys.argv[2]))
PY
